import { formatEuros } from './money.js';
import { getCustomer } from './customers.js';
import { lineTotal, lineDiscount, invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text.
 * Amounts are formatted using formatEuros().
 * @param {{ number?: string, customerId: string, issueDate?: string, dueDate?: string, lines: Array, voucher?: { code: string, amount: number }, payments?: Array }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  // Get invoice number or "DRAFT"
  const numberLine = invoice.number || 'DRAFT';

  // Get customer name
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : '[Unknown Customer]';

  // Build lines
  const lines = [numberLine, customerName];

  // Add invoice lines
  for (const line of invoice.lines) {
    const lineTotalResult = lineTotal(line);
    const lineTextParts = [
      `${line.qty} x ${line.name}`,
      `@ ${formatEuros(line.unitPrice)}`,
    ];

    if (lineTotalResult.ok) {
      lineTextParts.push(`= ${formatEuros(lineTotalResult.value)}`);

      // Add discount if present (includes bulk discount)
      const discountResult = lineDiscount(line);
      if (discountResult.ok && discountResult.value > 0) {
        lineTextParts.push(`(−${formatEuros(discountResult.value)})`);
      }
    }

    lines.push(lineTextParts.join(' '));
  }

  // Add totals
  const totalsResult = invoiceTotals(invoice);
  if (totalsResult.ok) {
    lines.push(`Subtotal: ${formatEuros(totalsResult.value.subtotal)}`);
    if (totalsResult.value.discount > 0) {
      lines.push(`Discount: −${formatEuros(totalsResult.value.discount)}`);
    }
    if (totalsResult.value.vat > 0) {
      lines.push(`VAT: ${formatEuros(totalsResult.value.vat)}`);
    }
    if (totalsResult.value.voucher > 0) {
      lines.push(`Voucher: −${formatEuros(totalsResult.value.voucher)}`);
    }
    lines.push(`Total: ${formatEuros(totalsResult.value.total)}`);
  }

  // Add due date if present
  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  // Add paid amount if payments exist
  if (Array.isArray(invoice.payments) && invoice.payments.length > 0) {
    const totalPaid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
    lines.push(`Paid: ${formatEuros(totalPaid)}`);
  }

  return lines.join('\n');
}

