3	import { renderInvoiceText } from '../src/render.js';
4	import { createInvoice, issueInvoice } from '../src/invoices.js';
5	
6	test('renderInvoiceText shows DRAFT for draft invoices', () => {
7	  const result = createInvoice({
8	    customerId: 'C-001',
9	    issueDate: '2025-02-15',
10	    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
11	  });
12	
13	  assert.equal(result.ok, true);
14	  const text = renderInvoiceText(result.value);
15	
16	  assert.match(text, /^DRAFT\n/);
17	});
18	
19	test('renderInvoiceText shows invoice number for issued invoices', () => {
20	  const result = createInvoice({
21	    customerId: 'C-001',
22	    issueDate: '2025-02-15',
23	    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
24	  });
25	
26	  assert.equal(result.ok, true);
27	  const issued = issueInvoice(result.value, []);
28	  assert.equal(issued.ok, true);
29	
30	  const text = renderInvoiceText(issued.value);
31	
32	  assert.match(text, /^INV-2025-0001\n/);
33	});
34	
