52	    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
53	  });
54	
55	  assert.equal(result.ok, true);
56	  const text = renderInvoiceText(result.value);
57	
58	  // Should contain: qty x name @ unitPrice = lineTotal
59	  assert.match(text, /10 x Development \(hour\) @ €95\.00 = €950\.00/);
60	});
61	
62	test('renderInvoiceText formats multiple lines correctly', () => {
63	  const result = createInvoice({
64	    customerId: 'C-001',
65	    issueDate: '2025-02-15',
