76	  assert.match(text, /5 x Sticker sheet @ €0\.50 = €2\.50/);
77	});
78	
79	test('renderInvoiceText includes total at the end', () => {
80	  const result = createInvoice({
81	    customerId: 'C-002', // standard tier, no discount
82	    issueDate: '2025-02-15',
83	    lines: [
84	      { sku: 'DEV-HOUR', qty: 10 },
85	      { sku: 'STICKER', qty: 5 },
86	    ],
87	  });
88	
89	  assert.equal(result.ok, true);
90	  const text = renderInvoiceText(result.value);
91	
92	  assert.match(text, /Subtotal: €952\.50/);
93	  assert.match(text, /VAT: €200\.02/);
94	  assert.match(text, /Total: €1,152\.52$/);
95	});
96	
97	test('renderInvoiceText single line structure', () => {
98	  const result = createInvoice({
99	    customerId: 'C-002',
100	    issueDate: '2025-02-15',
101	    lines: [{ sku: 'STICKER', qty: 100 }],
102	  });
103	
104	  assert.equal(result.ok, true);
