test('renderInvoiceText with voucher, due date, and paid', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);

  // Create invoice with all three new fields
  const completeInvoice = {
    ...issued.value,
    voucher: { code: 'SAVE10', amount: 3000 },
    dueDate: '2025-03-15',
    payments: [
      { amount: 15000, date: '2025-02-20' },
      { amount: 10000, date: '2025-02-25' },
    ],
  };

  const text = renderInvoiceText(completeInvoice);
  const lines = text.split('\n');

  // Should have: number, customer, 1 item, subtotal, voucher, total, due, paid
  // Verify all key elements are present
  assert.match(text, /INV-2025-0001/);
  assert.match(text, /Blue Fern Bakery/);
  assert.match(text, /5 x Development/);
  assert.match(text, /Subtotal:/);
  assert.match(text, /Voucher: −€30\.00/);
  assert.match(text, /Total:/);
  assert.match(text, /Due: 2025-03-15/);
  assert.match(text, /Paid: €250\.00/);

  // Verify order: voucher should appear before total, due and paid should be at end
  const voucherIndex = text.indexOf('Voucher:');
  const totalIndex = text.indexOf('Total:');
  const dueIndex = text.indexOf('Due:');
  const paidIndex = text.indexOf('Paid:');

  assert.ok(voucherIndex < totalIndex, 'Voucher should appear before Total');
  assert.ok(totalIndex < dueIndex, 'Total should appear before Due');
  assert.ok(dueIndex < paidIndex, 'Due should appear before Paid');
});

