91	/**
92	 * Add a line to an invoice, or increase qty if SKU already exists.
93	 * @param {{ status: string, lines: Array }} invoice
94	 * @param {{ sku: string, qty: number, discountPercent?: number }} input
95	 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
96	 */
97	export function addLine(invoice, { sku, qty, discountPercent }) {
98	  // Validate status is 'draft'
99	  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
100	
101	  // Validate qty is positive integer
102	  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');
103	
104	  // Validate discountPercent if provided
105	  if (discountPercent !== undefined) {
106	    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
107	      return fail('DISCOUNT_INVALID');
108	    }
109	  }
110	
111	  // Get customer to know their tier for new lines
112	  const customerResult = getCustomer(invoice.customerId);
113	  if (!customerResult.ok) return customerResult;
114	  const tierDiscount = TIER_DISCOUNTS[customerResult.value.tier] ?? 0;
115	
116	  // Get product
117	  const productResult = getProduct(sku);
118	  if (!productResult.ok) return productResult;
119	
120	  const { name, unitPrice, vatRate } = productResult.value;
121	
122	  // Find existing line with this SKU
123	  const existingLineIndex = invoice.lines.findIndex((l) => l.sku === sku);
124	
125	  let newLines;
126	  if (existingLineIndex >= 0) {
127	    // Update existing line's qty and discount
128	    const newQty = invoice.lines[existingLineIndex].qty + qty;
129	    const finalDiscount = discountPercent !== undefined ? discountPercent : invoice.lines[existingLineIndex].discountPercent;
130	    newLines = invoice.lines.map((line, i) =>
131	      i === existingLineIndex
132	        ? { ...line, qty: newQty, discountPercent: finalDiscount }
133	        : line
134	    );
135	  } else {
136	    // Add new line at the end, using tier discount if no explicit discount provided
137	    const finalDiscount = discountPercent !== undefined ? discountPercent : tierDiscount;
138	    newLines = [...invoice.lines, { sku, name, qty, unitPrice, vatRate, discountPercent: finalDiscount }];
139	  }
140	
141	  return ok({
142	    ...invoice,
143	    lines: newLines,
144	  });
145	}
