173	/**
174	 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
175	 * @param {{ status: string, issueDate: string }} invoice
176	 * @param {string[]} existingNumbers - Array of invoice numbers already used
177	 * @returns {{ ok: true, value: { number: string, status: string } } | { ok: false, error: string }}
178	 */
179	export function issueInvoice(invoice, existingNumbers) {
180	  // Validate status is 'draft'
181	  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
182	
183	  // Get next invoice number
184	  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);
185	
186	  // Return new invoice with number and status changed to 'issued'
187	  return ok({
188	    ...invoice,
189	    number,
190	    status: 'issued',
191	  });
192	}
193	
194	/**
195	 * Apply a voucher to a draft invoice.
196	 * @param {{ status: string, voucher?: { code: string, amount: number } }} invoice
197	 * @param {{ code: string, amount: number }} voucher
198	 * @returns {{ ok: true, value: { status: string, voucher: { code: string, amount: number } } } | { ok: false, error: string }}
199	 */
200	export function applyVoucher(invoice, { code, amount }) {
201	  // Validate status is 'draft'
202	  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
203	
204	  // Check if voucher already exists
205	  if (invoice.voucher) return fail('VOUCHER_EXISTS');
206	
207	  // Validate amount is a positive integer
208	  if (!Number.isInteger(amount) || amount <= 0) return fail('AMOUNT_INVALID');
209	
210	  return ok({
211	    ...invoice,
212	    voucher: { code, amount },
213	  });
214	}
