1	import { formatEuros } from './money.js';
2	import { getCustomer } from './customers.js';
3	import { lineTotal, lineDiscount, invoiceTotals } from './invoices.js';
4	
5	/**
6	 * Render an invoice as plain text.
7	 * Amounts are formatted using formatEuros().
8	 * @param {{ number?: string, customerId: string, issueDate?: string, dueDate?: string, lines: Array, voucher?: { code: string, amount: number }, payments?: Array }} invoice
9	 * @returns {string}
10	 */
11	export function renderInvoiceText(invoice) {
12	  // Get invoice number or "DRAFT"
13	  const numberLine = invoice.number || 'DRAFT';
14	
15	  // Get customer name
16	  const customerResult = getCustomer(invoice.customerId);
17	  const customerName = customerResult.ok ? customerResult.value.name : '[Unknown Customer]';
18	
19	  // Build lines
20	  const lines = [numberLine, customerName];
21	
22	  // Add invoice lines
23	  for (const line of invoice.lines) {
24	    const lineTotalResult = lineTotal(line);
25	    const lineTextParts = [
26	      `${line.qty} x ${line.name}`,
27	      `@ ${formatEuros(line.unitPrice)}`,
28	    ];
29	
30	    if (lineTotalResult.ok) {
31	      lineTextParts.push(`= ${formatEuros(lineTotalResult.value)}`);
32	
33	      // Add discount if present (includes bulk discount)
34	      const discountResult = lineDiscount(line);
35	      if (discountResult.ok && discountResult.value > 0) {
36	        lineTextParts.push(`(−${formatEuros(discountResult.value)})`);
37	      }
38	    }
39	
40	    lines.push(lineTextParts.join(' '));
41	  }
42	
43	  // Add totals
44	  const totalsResult = invoiceTotals(invoice);
45	  if (totalsResult.ok) {
46	    lines.push(`Subtotal: ${formatEuros(totalsResult.value.subtotal)}`);
47	    if (totalsResult.value.discount > 0) {
48	      lines.push(`Discount: −${formatEuros(totalsResult.value.discount)}`);
49	    }
50	    if (totalsResult.value.vat > 0) {
51	      lines.push(`VAT: ${formatEuros(totalsResult.value.vat)}`);
52	    }
53	    if (totalsResult.value.voucher > 0) {
54	      lines.push(`Voucher: −${formatEuros(totalsResult.value.voucher)}`);
55	    }
56	    lines.push(`Total: ${formatEuros(totalsResult.value.total)}`);
57	  }
58	
59	  // Add due date if present
60	  if (invoice.dueDate) {
61	    lines.push(`Due: ${invoice.dueDate}`);
62	  }
63	
64	  // Add paid amount if payments exist
65	  if (Array.isArray(invoice.payments) && invoice.payments.length > 0) {
66	    const totalPaid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
67	    lines.push(`Paid: ${formatEuros(totalPaid)}`);
68	  }
69	
70	  return lines.join('\n');
71	}
